import React, { useEffect, useState } from 'react';
import { collection, query, where, getDocs, updateDoc, doc, deleteDoc, serverTimestamp } from 'firebase/firestore';
import { db } from '@/firebase';
import { Radio } from 'lucide-react';

/**
 * طلبات تفعيل «جهاز الخطوط» (مودم متعدد الخطوط) — تظهر في لوحة الإدمن وتفعّل إزالة البلور عند الموافقة
 */
export const LineDeviceGatewayRequestsPanel = ({ adminId }: { adminId: string }) => {
  const [requests, setRequests] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<'pending' | 'approved' | 'rejected'>('pending');

  const fetchRequests = async () => {
    setLoading(true);
    try {
      const q = query(collection(db, 'lineDeviceGatewayRequests'), where('status', '==', activeTab));
      const snap = await getDocs(q);
      const data = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
      data.sort((a: any, b: any) => {
        const dateA = a.createdAt?.seconds ?? a.createdAt?._seconds ?? 0;
        const dateB = b.createdAt?.seconds ?? b.createdAt?._seconds ?? 0;
        return dateB - dateA;
      });
      setRequests(data);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchRequests();
  }, [activeTab]);

  const handleApprove = async (req: any) => {
    if (!window.confirm(`تأكيد تفعيل جهاز الخطوط للمستخدم؟`)) return;
    try {
      await updateDoc(doc(db, 'profiles', req.userId), {
        lineDeviceGatewayUnlocked: true,
        lineDeviceGatewayApprovedAt: serverTimestamp(),
      });
      await updateDoc(doc(db, 'lineDeviceGatewayRequests', req.id), {
        status: 'approved',
        approvedBy: adminId,
        approvedAt: serverTimestamp(),
      });
      alert('تم التفعيل — سيختفي قفل قسم المودم عند المستخدم.');
      fetchRequests();
    } catch (e) {
      console.error(e);
      alert('حدث خطأ أثناء التفعيل');
    }
  };

  const handleReject = async (req: any) => {
    if (!window.confirm('رفض هذا الطلب؟')) return;
    try {
      await updateDoc(doc(db, 'lineDeviceGatewayRequests', req.id), {
        status: 'rejected',
        rejectedBy: adminId,
        rejectedAt: serverTimestamp(),
      });
      await updateDoc(doc(db, 'profiles', req.userId), {
        lineDeviceGatewayUnlocked: false,
      });
      fetchRequests();
    } catch (e) {
      console.error(e);
      alert('حدث خطأ');
    }
  };

  const handleDelete = async (req: any) => {
    if (!window.confirm('حذف الطلب نهائياً؟')) return;
    try {
      await deleteDoc(doc(db, 'lineDeviceGatewayRequests', req.id));
      fetchRequests();
    } catch (e) {
      console.error(e);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-2 text-slate-800">
        <Radio className="h-6 w-6 text-violet-600" />
        <h2 className="text-xl font-bold">تفعيل الجهاز</h2>
      </div>
      <p className="text-sm text-gray-600 max-w-3xl">
        طلبات المستخدمين من لوحة التحكم (أيقونة «جهاز خطوط»): رقم الجهاز وعدد الأجهزة/الخطوط. عند الموافقة يُفعَّل لهم فتح نافذة المودم (USB) فوراً.
      </p>

      <div className="flex gap-2 border-b border-gray-200 pb-2">
        {(['pending', 'approved', 'rejected'] as const).map((t) => (
          <button
            key={t}
            type="button"
            onClick={() => setActiveTab(t)}
            className={`px-4 py-2 rounded-lg text-sm font-medium ${
              activeTab === t ? 'bg-violet-100 text-violet-800' : 'text-gray-500 hover:bg-gray-100'
            }`}
          >
            {t === 'pending' ? 'معلقة' : t === 'approved' ? 'مفعّلة' : 'مرفوضة'}
          </button>
        ))}
      </div>

      {loading ? (
        <p className="text-gray-500">جاري التحميل...</p>
      ) : (
        <div className="overflow-x-auto rounded-lg border border-gray-200 bg-white shadow-sm">
          <table className="min-w-full text-sm">
            <thead className="bg-gray-50 border-b">
              <tr>
                <th className="px-4 py-3 text-right">البريد</th>
                <th className="px-4 py-3 text-right">رقم الجهاز</th>
                <th className="px-4 py-3 text-right">عدد الخطوط</th>
                <th className="px-4 py-3 text-right">المستخدم</th>
                <th className="px-4 py-3 text-right">إجراءات</th>
              </tr>
            </thead>
            <tbody>
              {requests.map((req) => (
                <tr key={req.id} className="border-b border-gray-100 hover:bg-gray-50/80">
                  <td className="px-4 py-3 font-mono text-xs">{req.email || '—'}</td>
                  <td className="px-4 py-3 font-mono text-xs">{req.deviceSerial || '—'}</td>
                  <td className="px-4 py-3">{req.lineCount ?? '—'}</td>
                  <td className="px-4 py-3 font-mono text-[11px] break-all max-w-[180px]">{req.userId || '—'}</td>
                  <td className="px-4 py-3 space-x-2 space-x-reverse">
                    {req.status === 'pending' && (
                      <>
                        <button
                          type="button"
                          className="px-3 py-1 rounded bg-emerald-600 text-white text-xs hover:bg-emerald-700"
                          onClick={() => handleApprove(req)}
                        >
                          موافقة
                        </button>
                        <button
                          type="button"
                          className="px-3 py-1 rounded bg-rose-100 text-rose-800 text-xs hover:bg-rose-200"
                          onClick={() => handleReject(req)}
                        >
                          رفض
                        </button>
                      </>
                    )}
                    <button
                      type="button"
                      className="px-3 py-1 rounded bg-gray-100 text-gray-700 text-xs"
                      onClick={() => handleDelete(req)}
                    >
                      حذف
                    </button>
                  </td>
                </tr>
              ))}
              {requests.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-4 py-10 text-center text-gray-500">
                    لا توجد طلبات
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};
